import{_ as t,o as a,c as i,a0 as s}from"./chunks/framework.l1I-fhud.js";const k=JSON.parse('{"title":"Scripting tamias","description":"","frontmatter":{},"headers":[],"relativePath":"reference/scripting.md","filePath":"reference/scripting.md"}'),d={name:"reference/scripting.md"};function o(r,e,c,n,h,l){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="scripting-tamias" tabindex="-1">Scripting tamias <a class="header-anchor" href="#scripting-tamias" aria-label="Permalink to &quot;Scripting tamias&quot;">​</a></h1><p>Everything an agent or CI job needs without scraping human output.</p><h2 id="json" tabindex="-1"><code>--json</code> <a class="header-anchor" href="#json" aria-label="Permalink to &quot;`--json`&quot;">​</a></h2><p>These verbs emit JSON with <code>--json</code>:</p><table tabindex="0"><thead><tr><th>verb</th><th>shape</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>{&quot;packages&quot;: [entry…]}</code> — record fields + <code>label</code>, <code>size</code>, <code>dir</code></td></tr><tr><td><code>info &lt;name&gt;</code></td><td>one entry object (same fields)</td></tr><tr><td><code>verify &lt;name&gt;</code></td><td><code>{name, recorded, computed, ok}</code> — non-zero exit on mismatch</td></tr><tr><td><code>update [name]</code></td><td><code>{&quot;updated&quot;: [label…]}</code> (with <code>--all</code> or a name)</td></tr><tr><td><code>doctor</code></td><td>per-check report — store, cache, git, registry, drivers</td></tr><tr><td><code>config</code></td><td><code>{file, search, config}</code> — the effective config</td></tr><tr><td><code>search &lt;q&gt;</code></td><td><code>{&quot;results&quot;: [{label, name, scope, version, kind, digest, file}]}</code></td></tr><tr><td><code>cache clean</code></td><td><code>{evicted, entries}</code></td></tr></tbody></table><p>Without <code>--json</code> the same verbs print aligned text.</p><h2 id="capability-discovery" tabindex="-1">Capability discovery <a class="header-anchor" href="#capability-discovery" aria-label="Permalink to &quot;Capability discovery&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manifest</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # {&quot;name&quot;,&quot;version&quot;,&quot;verbs&quot;:[…]} — verbs generated from the parser</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # JSON Schema for the package manifest (tamias.yaml)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen-cli-docs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # this CLI reference, regenerated from clap</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> completions</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">zsh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fish</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">elvish</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">powershell</span></span></code></pre></div><p><code>manifest</code>&#39;s verb list can&#39;t drift — it&#39;s generated from the clap tree each run.</p><h2 id="tamias-serve" tabindex="-1"><code>tamias serve</code> <a class="header-anchor" href="#tamias-serve" aria-label="Permalink to &quot;`tamias serve`&quot;">​</a></h2><p>For stateful, interactive use, <code>tamias serve</code> speaks ndjson JSON-RPC over stdio — see <a href="/tamias/reference/serve.html">the serve reference</a>.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>var</th><th>effect</th></tr></thead><tbody><tr><td><code>TAMIAS_HOME</code></td><td>store + <code>drivers/</code> root (default <code>~/.local/share/tamias</code>)</td></tr><tr><td><code>TAMIAS_CACHE</code></td><td>fetch-cache root (default <code>~/.cache/tamias/fetch</code>)</td></tr><tr><td><code>TAMIAS_REGISTRY</code></td><td>default registry root for <code>publish</code>/<code>search</code></td></tr><tr><td><code>TAMIAS_ALLOW_DRIVERS</code></td><td><code>=1</code> consents to bundled <code>drivers/</code> (same as <code>--allow-drivers</code>)</td></tr><tr><td><code>TAMIAS_REGISTRY_TOKEN</code></td><td>bearer token for http(s) registries</td></tr><tr><td><code>TAMIAS_REGISTRY_SERVE_TOKEN</code></td><td>require auth on <code>tamias registry serve</code></td></tr><tr><td><code>TAMIAS_OTEL_*</code> / <code>OTEL_*</code></td><td>opt-in telemetry — see <a href="/tamias/explanation/architecture.html#observability">Architecture</a></td></tr></tbody></table><p><code>tamias config --file &lt;path&gt;</code> overrides discovery for that invocation; without it, <code>tamias config</code> reads the first of <code>./tamias.yml</code>, <code>./tamias.yaml</code>, <code>./tamias.toml</code> it finds.</p><h2 id="exit-codes" tabindex="-1">Exit codes <a class="header-anchor" href="#exit-codes" aria-label="Permalink to &quot;Exit codes&quot;">​</a></h2><p>A failed verb exits non-zero. <code>verify</code> fails on digest mismatch; <code>doctor</code> fails if any check fails (the report still prints first). <code>cache clean --all</code> and <code>--days</code> conflict — pick one.</p>',16)])])}const m=t(d,[["render",o]]);export{k as __pageData,m as default};
